-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- Maschinen mit Position (linke obere Ecke) und Stellfläche im Gebäude (m)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- Techniker (zwei pro Standort)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- Ersatzteile (zentrales Lager, einige bewusst unter Mindestbestand)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- Störmeldungen (älteste zuerst)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- Wartungsaufträge (genau einer pro Störmeldung)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- Verwendete Ersatzteile
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- Bestellungen (Historie + zwei offene)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- Fortlaufende Nummern hinter die vergebenen IDs setzen, damit neue
-- Einträge aus der Webanwendung lückenlos weiterzählen
-- ---------------------------------------------------------------------
SELECT setval(pg_get_serial_sequence('standort', 'id'), (SELECT max(id) FROM standort));
SELECT setval(pg_get_serial_sequence('gebaeude', 'id'), (SELECT max(id) FROM gebaeude));
SELECT setval(pg_get_serial_sequence('maschine', 'id'), (SELECT max(id) FROM maschine));
SELECT setval(pg_get_serial_sequence('techniker', 'id'), (SELECT max(id) FROM techniker));
SELECT setval(pg_get_serial_sequence('ersatzteil', 'id'), (SELECT max(id) FROM ersatzteil));
SELECT setval(pg_get_serial_sequence('stoermeldung', 'id'), (SELECT max(id) FROM stoermeldung));
SELECT setval(pg_get_serial_sequence('wartungsauftrag', 'id'), (SELECT max(id) FROM wartungsauftrag));
